import {samples,stages,descriptors,preferences,             } from '../game/content.js';
                                            
export const nameOf=(id         )=>samples.find(s=>s[0]===id) [1];
export const detailOf=(id         )=>samples.find(s=>s[0]===id) [2];
const bulb='<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M9 18h6m-5 3h4M12 1v2m10 9h-2M4 12H2m3-7 2 2m12-2-2 2M9 16v-1a6 6 0 1 1 6 0v1"/></svg>';
const box='<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 5h16l2 7-2 7H4l-2-7zm-2 7h6l2 3h4l2-3h6"/></svg>';
const button=(action       ,value              ,label       ,cls='',extra='')=>'<button data-key="'+action+'-'+value+'" data-action="'+action+'" value="'+value+'" class="'+cls+'" '+extra+'>'+label+'</button>';
const stage=(i       ,label       ,primary=false)=>button('stage',i,label,primary?'primary':'');
const selected=(label       ,id       ,idNow       )=>'<option value="'+id+'" '+(id===idNow?'selected':'')+'>'+label+'</option>';
const chooser=(s      )=>'<label>Amostra na bancada<select data-key="select" data-action="select">'+s.pool.map(id=>selected(nameOf(id),id,s.sampleId)).join('')+'</select></label>';
const adjust=(action       ,minus       ,plus       ,caption       ,value       )=>'<div class="adjust"><span>'+caption+' <strong>'+value+'</strong></span>'+button(action,minus,'−','','aria-label="Diminuir '+caption+'"')+button(action,plus,'+','','aria-label="Aumentar '+caption+'"')+'</div>';
const zoom=(s      )=>adjust('zoom',-.5,.5,'Lupa',s.zoom+'×')+(s.zoom>1?'<div class="actions directions">'+[['-.2,0','←','Mover lupa à esquerda'],['.2,0','→','Mover lupa à direita'],['0,-.2','↑','Mover lupa para trás'],['0,.2','↓','Mover lupa para frente']].map(([v,l,a])=>button('move',v,l,'','aria-label="'+a+'"')).join('')+'</div>':'');
const save=()=>button('save','now',box+' Guardar','wide');
export function setupHtml(){return '<p class="eyebrow">ATELIÊ DE OBSERVAÇÃO</p><h2>Atlas das Texturas</h2><p>Explore oito superfícies e registre o que você percebe ao mudar a luz e aproximar os detalhes.</p><label>Modo de exploração<select><option value="livre">Livre</option><option value="guiado">Guiado</option><option value="acompanhado">Acompanhado</option></select></label><fieldset hidden><legend>Amostras disponíveis</legend><div class="checks">'+samples.map(([id,n],i)=>'<label><input type="checkbox" value="'+id+'" '+(i<2?'checked':'')+'>'+n+'</label>').join('')+'</div><p role="status"></p></fieldset><div class="actions"><button class="primary" value="start">Começar</button><button value="demo">Ver demonstração</button></div>';}
export function panelHtml(s      ,status       ,hint        ){
 const steps='<nav aria-label="Etapas">'+stages.map((name,i)=>stage(i,'<span class="sr">'+name+'</span><span aria-hidden="true">●</span>',i===s.stage)).join('')+'</nav>';
 let body='';
 switch(s.stage){
 case 0:body='<p>Escolha duas superfícies para investigar.</p>'+chooser(s)+'<label>Comparar com<select data-key="pair" data-action="pair">'+s.pool.filter(id=>id!==s.sampleId).map(id=>selected(nameOf(id),id,s.pair[1])).join('')+'</select></label>'+stage(1,'Observar amostras',true);break;
 case 1:body=chooser(s)+adjust('rotate',-15,15,'Rotação',Math.round(s.rotation)+'°')+zoom(s)+stage(2,'Acender luz rasante',true);break;
 case 2:body=button('light',s.lampAngle>=75?-150:25,bulb+' Girar a luz','primary wide')+save()+adjust('light',-15,15,'Ângulo',Math.round(s.lampAngle)+'°')+adjust('elevation',-5,5,'Altura',s.lampElevation+'°')+'<div class="actions">'+stage(3,'Comparar')+button('hint','show','✋ Dica','','aria-expanded="'+hint+'"')+'</div>';break;
 case 3:body='<p>As duas amostras usam a mesma câmera, escala e iluminação.</p>'+chooser(s)+'<label>Comparar com<select data-key="pair" data-action="pair">'+s.pool.filter(id=>id!==s.sampleId).map(id=>selected(nameOf(id),id,s.pair[1])).join('')+'</select></label>'+adjust('light',-15,15,'Ângulo',Math.round(s.lampAngle)+'°')+adjust('rotate',-15,15,'Rotação',Math.round(s.rotation)+'°')+'<fieldset><legend>Como você descreveria a amostra na bancada?</legend><div class="pills">'+descriptors.map(d=>button('describe',d,d,'','aria-pressed="'+s.descriptors.includes(d)+'"')).join('')+'</div></fieldset>'+stage(4,'Abrir atlas',true);break;
 case 4:body=chooser(s)+'<fieldset><legend>Descritores opcionais</legend><div class="pills">'+descriptors.map(d=>button('describe',d,d,'','aria-pressed="'+s.descriptors.includes(d)+'"')).join('')+'</div></fieldset><label>Preferência opcional<select data-key="prefer" data-action="prefer">'+selected('Omitir','',s.preference)+preferences.map(p=>selected(p,p,s.preference)).join('')+'</select></label>'+save()+stage(5,'Revisar coleção',true);break;
 case 5:body='<p>'+s.collection.length+' de 8 amostras guardadas.</p><ul class="entries">'+s.collection.map(e=>'<li><div><strong>'+nameOf(e.id)+'</strong><small>'+[...e.descriptors,e.preference].filter(Boolean).join(' · ')+'</small></div>'+button('remove',e.id,'Retirar','','aria-label="Retirar '+nameOf(e.id)+'"')+'</li>').join('')+'</ul><div class="actions">'+stage(0,'Explorar mais',true)+button('export','json','Exportar JSON')+'</div>';break;
 }
 return '<div class="handle"></div><div class="step"><span>Etapa '+(s.stage+1)+' de '+stages.length+'</span>'+steps+'</div><h2 tabindex="-1">'+stages[s.stage]+'</h2>'+body+(hint?'<p class="hint">'+detailOf(s.sampleId)+' Observe onde as sombras crescem ao baixar a luminária.</p>':'')+(s.mode==='guiado'&&s.stage!==2?'<p class="hint">'+['Escolha materiais com formas diferentes.','Procure detalhes que aparecem quando a amostra gira.','','Compare o contorno das sombras.','Escolha as palavras que fazem sentido para você.','Leia suas observações lado a lado.'][s.stage]+'</p>':'')+(status?'<p class="feedback">'+status+'</p>':'')+'<footer>'+(s.stage>0?stage(s.stage-1,'Voltar'):'')+(s.stage<5?button('skip','next','Pular'):'')+button('pause','now','Pausar')+button('mute','toggle',s.muted?'Som desligado':'Som ligado')+button('motion','toggle',s.reduced?'Movimento reduzido':'Movimento normal')+button('reset','ask','Reiniciar')+'</footer>';
}

